theme.css:
/* ==== INTERFACE ====
   token  --bg #F3F5F7          页面底色｜微冷碑石灰白
   token  --text #11161B        正文字体色｜浓墨深黑
   token  --muted #536070       辅助信息、边框线条、次要引文｜石青灰
   token  --focus #B93829       当前焦点、朱批断语、太史公论断｜朱砂红
   token  --ben #1E3A5F         本传纪事、正史主干、明叙功烈｜墨靛蓝
   token  --hu #226752          他传互见、幽微细节、伏脉别出｜松烟绿
   token  --font-serif          正文引文字体｜宋体/典籍衬线
   token  --font-sans           标题与界标字体｜无衬线清晰字体
   token  --fs-h1 34px          页标题字号
   token  --fs-h2 22px          区块标题字号
   token  --fs-lead 19px        导语字号
   token  --fs-body 18px        正文字号
   token  --fs-sec 16px         次级成句字号
   token  --fs-label 15px       标签与徽记字号
   token  --fs-tick 13px        时间线与图示刻度字号
   版心   1488×844              #stage 已含 padding
   版式   .focus                标题后单一主区
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;
  --bg: #F3F5F7;
  --text: #11161B;
  --muted: #536070;
  --focus: #B93829;
  --ben: #1E3A5F;
  --hu: #226752;
  --font-serif: "Source Han Serif SC", "Noto Serif CJK SC", "Songti SC", SimSun, STSong, serif;
  --font-sans: "Source Han Sans SC", "Noto Sans CJK SC", "PingFang SC", "Microsoft YaHei", sans-serif;
  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;
  --lh-body: 1.6;
  --lh-tight: 1.35;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
}

.focus {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

svg .bar, svg .cell, svg .box {
  width: auto;
  height: auto;
}
